# Phosphor draws on a 256 grid and fills rather than strokes, so an icon needs
# neither stroke attributes nor a size beyond the box the component gives it.
bc_icon <- function(name, size = 24, class = NULL) {
  HTML(paste0(
    '<svg xmlns="http://www.w3.org/2000/svg" width="', size, '" height="', size,
    '" viewBox="0 0 256 256" fill="currentColor"',
    if (!is.null(class)) paste0(' class="', class, '"'),
    ' aria-hidden="true">',
    bc_icon_paths[[name]],
    "</svg>"
  ))
}

# An `icon` argument is the caller's tag when they give one and the component's
# own when they do not. NULL from a caller means the default, so an icon can
# only be dropped by passing something empty.
bc_icon_or <- function(icon, name, size = 24, class = NULL) {
  icon %||% bc_icon(name, size = size, class = class)
}
